U_corr_mast3_20241028_2030_2100_stow_z2[U_corr_mast3_20241028_2030_2100_stow_z2.isna()==False] = scipy.signal.detrend(U_corr_mast3_20241028_2030_2100_stow_z2.dropna()) 
U_corr_mast3_20241028_2030_2100_stow_z3[U_corr_mast3_20241028_2030_2100_stow_z3.isna()==False] = scipy.signal.detrend(U_corr_mast3_20241028_2030_2100_stow_z3.dropna()) 

V_corr_mast3_20241028_2030_2100_stow_z1[V_corr_mast3_20241028_2030_2100_stow_z1.isna()==False] = scipy.signal.detrend(V_corr_mast3_20241028_2030_2100_stow_z1.dropna()) 
