W_corr_mast3_20241028_2030_2100_stow_z1[W_corr_mast3_20241028_2030_2100_stow_z1.isna()==False] = scipy.signal.detrend(W_corr_mast3_20241028_2030_2100_stow_z1.dropna()) 
