# Reynolds stresses and length scales (soutH3)

mast3_uv_z1_20241028_2030_2100_stow = (U_corr_mast3_20241028_2030_2100_stow_z1*V_corr_mast3_20241028_2030_2100_stow_z1).mean()-(U_corr_mast3_20241028_2030_2100_stow_z1.mean()*V_corr_mast3_20241028_2030_2100_stow_z1.mean());
mast3_vw_z1_20241028_2030_2100_stow = (V_corr_mast3_20241028_2030_2100_stow_z1*W_corr_mast3_20241028_2030_2100_stow_z1).mean()-(V_corr_mast3_20241028_2030_2100_stow_z1.mean()*W_corr_mast3_20241028_2030_2100_stow_z1.mean());
