utau_mast1_z3_20241028_1820_1850_operation = (mast1_uw_z3_20241028_1820_1850_operation**2+mast1_vw_z3_20241028_1820_1850_operation**2)**(1/4) 

L_mast1_z1_20241028_1820_1850_operation = -1*(utau_mast1_z1_20241028_1820_1850_operation**3)/(0.4*(9.81/H2_Ts_20241028_1820_1850_operation_z1)*mast1_wT_z1_20241028_1820_1850_operation)
L_mast1_z2_20241028_1820_1850_operation = -1*(utau_mast1_z2_20241028_1820_1850_operation**3)/(0.4*(9.81/H2_Ts_20241028_1820_1850_operation_z2)*mast1_wT_z2_20241028_1820_1850_operation)
L_mast1_z3_20241028_1820_1850_operation = -1*(utau_mast1_z3_20241028_1820_1850_operation**3)/(0.4*(9.81/H2_Ts_20241028_1820_1850_operation_z3)*mast1_wT_z3_20241028_1820_1850_operation)

zL_mast1_z1_20241028_1820_1850_operation = heights[0]/L_mast1_z1_20241028_1820_1850_operation
zL_mast1_z2_20241028_1820_1850_operation = heights[1]/L_mast1_z2_20241028_1820_1850_operation
zL_mast1_z3_20241028_1820_1850_operation = heights[2]/L_mast1_z3_20241028_1820_1850_operation

mast1_uprimewprime_z1_20241028_1820_1850_operation = (U_corr_mast1_20241028_1820_1850_operation_z1*W_corr_mast1_20241028_1820_1850_operation_z1);
mast1_uprimewprime_z2_20241028_1820_1850_operation = (U_corr_mast1_20241028_1820_1850_operation_z2*W_corr_mast1_20241028_1820_1850_operation_z2);
mast1_uprimewprime_z3_20241028_1820_1850_operation = (U_corr_mast1_20241028_1820_1850_operation_z3*W_corr_mast1_20241028_1820_1850_operation_z3);


