W_corr_mast3_20241028_1820_1850_operation_z1[W_corr_mast3_20241028_1820_1850_operation_z1.isna()==False] = scipy.signal.detrend(W_corr_mast3_20241028_1820_1850_operation_z1.dropna()) 
W_corr_mast3_20241028_1820_1850_operation_z2[W_corr_mast3_20241028_1820_1850_operation_z2.isna()==False] = scipy.signal.detrend(W_corr_mast3_20241028_1820_1850_operation_z2.dropna()) 
W_corr_mast3_20241028_1820_1850_operation_z3[W_corr_mast3_20241028_1820_1850_operation_z3.isna()==False] = scipy.signal.detrend(W_corr_mast3_20241028_1820_1850_operation_z3.dropna()) 

Ts_corr_mast3_20241028_1820_1850_operation_z1[Ts_corr_mast3_20241028_1820_1850_operation_z1.isna()==False] = scipy.signal.detrend(Ts_corr_mast3_20241028_1820_1850_operation_z1.dropna()) 
