Ts_corr_mast3_20241028_1820_1850_operation_z3[Ts_corr_mast3_20241028_1820_1850_operation_z3.isna()==False] = scipy.signal.detrend(Ts_corr_mast3_20241028_1820_1850_operation_z3.dropna()) 

# Reynolds stresses and length scales (soutH3)

mast3_uv_z1_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z1*V_corr_mast3_20241028_1820_1850_operation_z1).mean()-(U_corr_mast3_20241028_1820_1850_operation_z1.mean()*V_corr_mast3_20241028_1820_1850_operation_z1.mean());
mast3_vw_z1_20241028_1820_1850_operation = (V_corr_mast3_20241028_1820_1850_operation_z1*W_corr_mast3_20241028_1820_1850_operation_z1).mean()-(V_corr_mast3_20241028_1820_1850_operation_z1.mean()*W_corr_mast3_20241028_1820_1850_operation_z1.mean());
mast3_uw_z1_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z1*W_corr_mast3_20241028_1820_1850_operation_z1).mean()-(U_corr_mast3_20241028_1820_1850_operation_z1.mean()*W_corr_mast3_20241028_1820_1850_operation_z1.mean());
mast3_wT_z1_20241028_1820_1850_operation = (W_corr_mast3_20241028_1820_1850_operation_z1*Ts_corr_mast3_20241028_1820_1850_operation_z1).mean()-(W_corr_mast3_20241028_1820_1850_operation_z1.mean()*Ts_corr_mast3_20241028_1820_1850_operation_z1.mean());

mast3_uv_z2_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z2*V_corr_mast3_20241028_1820_1850_operation_z2).mean()-(U_corr_mast3_20241028_1820_1850_operation_z2.mean()*V_corr_mast3_20241028_1820_1850_operation_z2.mean());
mast3_vw_z2_20241028_1820_1850_operation = (V_corr_mast3_20241028_1820_1850_operation_z2*W_corr_mast3_20241028_1820_1850_operation_z2).mean()-(V_corr_mast3_20241028_1820_1850_operation_z2.mean()*W_corr_mast3_20241028_1820_1850_operation_z2.mean());
mast3_uw_z2_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z2*W_corr_mast3_20241028_1820_1850_operation_z2).mean()-(U_corr_mast3_20241028_1820_1850_operation_z2.mean()*W_corr_mast3_20241028_1820_1850_operation_z2.mean());
mast3_wT_z2_20241028_1820_1850_operation = (W_corr_mast3_20241028_1820_1850_operation_z2*Ts_corr_mast3_20241028_1820_1850_operation_z2).mean()-(W_corr_mast3_20241028_1820_1850_operation_z2.mean()*Ts_corr_mast3_20241028_1820_1850_operation_z2.mean());

mast3_uv_z3_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z3*V_corr_mast3_20241028_1820_1850_operation_z3).mean()-(U_corr_mast3_20241028_1820_1850_operation_z3.mean()*V_corr_mast3_20241028_1820_1850_operation_z3.mean());
mast3_vw_z3_20241028_1820_1850_operation = (V_corr_mast3_20241028_1820_1850_operation_z3*W_corr_mast3_20241028_1820_1850_operation_z3).mean()-(V_corr_mast3_20241028_1820_1850_operation_z3.mean()*W_corr_mast3_20241028_1820_1850_operation_z3.mean());
mast3_uw_z3_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z3*W_corr_mast3_20241028_1820_1850_operation_z3).mean()-(U_corr_mast3_20241028_1820_1850_operation_z3.mean()*W_corr_mast3_20241028_1820_1850_operation_z3.mean());
mast3_wT_z3_20241028_1820_1850_operation = (W_corr_mast3_20241028_1820_1850_operation_z3*Ts_corr_mast3_20241028_1820_1850_operation_z3).mean()-(W_corr_mast3_20241028_1820_1850_operation_z3.mean()*Ts_corr_mast3_20241028_1820_1850_operation_z3.mean());

utau_mast3_z1_20241028_1820_1850_operation = (mast3_uw_z1_20241028_1820_1850_operation**2+mast3_vw_z1_20241028_1820_1850_operation**2)**(1/4) 
utau_mast3_z2_20241028_1820_1850_operation = (mast3_uw_z2_20241028_1820_1850_operation**2+mast3_vw_z2_20241028_1820_1850_operation**2)**(1/4) 
utau_mast3_z3_20241028_1820_1850_operation = (mast3_uw_z3_20241028_1820_1850_operation**2+mast3_vw_z3_20241028_1820_1850_operation**2)**(1/4) 

L_mast3_z1_20241028_1820_1850_operation = -1*(utau_mast3_z1_20241028_1820_1850_operation**3)/(0.4*(9.81/H3_Ts_20241028_1820_1850_operation_z1)*mast3_wT_z1_20241028_1820_1850_operation)
L_mast3_z2_20241028_1820_1850_operation = -1*(utau_mast3_z2_20241028_1820_1850_operation**3)/(0.4*(9.81/H3_Ts_20241028_1820_1850_operation_z2)*mast3_wT_z2_20241028_1820_1850_operation)
L_mast3_z3_20241028_1820_1850_operation = -1*(utau_mast3_z3_20241028_1820_1850_operation**3)/(0.4*(9.81/H3_Ts_20241028_1820_1850_operation_z3)*mast3_wT_z3_20241028_1820_1850_operation)

zL_mast3_z1_20241028_1820_1850_operation = heights[0]/L_mast3_z1_20241028_1820_1850_operation
zL_mast3_z2_20241028_1820_1850_operation = heights[1]/L_mast3_z2_20241028_1820_1850_operation
zL_mast3_z3_20241028_1820_1850_operation = heights[2]/L_mast3_z3_20241028_1820_1850_operation

mast3_uprimewprime_z1_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z1*W_corr_mast3_20241028_1820_1850_operation_z1);
mast3_uprimewprime_z2_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z2*W_corr_mast3_20241028_1820_1850_operation_z2);
mast3_uprimewprime_z3_20241028_1820_1850_operation = (U_corr_mast3_20241028_1820_1850_operation_z3*W_corr_mast3_20241028_1820_1850_operation_z3);


