inflow_vw_z3_20241115_2145_2215_stow = (V_corr_inflow_20241115_2145_2215_stow_z3*W_corr_inflow_20241115_2145_2215_stow_z3).mean()-(V_corr_inflow_20241115_2145_2215_stow_z3.mean()*W_corr_inflow_20241115_2145_2215_stow_z3.mean());
inflow_uw_z3_20241115_2145_2215_stow = (U_corr_inflow_20241115_2145_2215_stow_z3*W_corr_inflow_20241115_2145_2215_stow_z3).mean()-(U_corr_inflow_20241115_2145_2215_stow_z3.mean()*W_corr_inflow_20241115_2145_2215_stow_z3.mean());
inflow_wT_z3_20241115_2145_2215_stow = (W_corr_inflow_20241115_2145_2215_stow_z3*Ts_corr_inflow_20241115_2145_2215_stow_z3).mean()-(W_corr_inflow_20241115_2145_2215_stow_z3.mean()*Ts_corr_inflow_20241115_2145_2215_stow_z3.mean());

utau_z1_20241115_2145_2215_stow = (inflow_uw_z1_20241115_2145_2215_stow**2+inflow_vw_z1_20241115_2145_2215_stow**2)**(1/4) 
utau_z2_20241115_2145_2215_stow = (inflow_uw_z2_20241115_2145_2215_stow**2+inflow_vw_z2_20241115_2145_2215_stow**2)**(1/4) 
utau_z3_20241115_2145_2215_stow = (inflow_uw_z3_20241115_2145_2215_stow**2+inflow_vw_z3_20241115_2145_2215_stow**2)**(1/4) 

L_z1_20241115_2145_2215_stow = -1*(utau_z1_20241115_2145_2215_stow**3)/(0.4*(9.81/H1_Ts_20241115_2145_2215_stow_z1)*inflow_wT_z1_20241115_2145_2215_stow)
L_z2_20241115_2145_2215_stow = -1*(utau_z2_20241115_2145_2215_stow**3)/(0.4*(9.81/H1_Ts_20241115_2145_2215_stow_z2)*inflow_wT_z2_20241115_2145_2215_stow)
