autocorr_inflow_20241115_2145_2215_stow = np.correlate(loads_inflow_20Hz_20241115_2145_2215_stow.U_ax_Top.dropna(), loads_inflow_20Hz_20241115_2145_2215_stow.U_ax_Top.dropna(), mode='full') 
