lags = np.arange(-len(loads_inflow_20Hz_20241115_2145_2215_stow.U_ax_Top.dropna()) + 1, len(loads_inflow_20Hz_20241115_2145_2215_stow.U_ax_Top.dropna()))
Y = (lags, autocorr_inflow_20241115_2145_2215_stow)
Lux_20241115_2145_2215_stow_z3 = Y[0][np.where(Y[1]==find_nearest(Y[1], value=1/np.e))]*(1/fs)*abs(H1_wspd_20241115_2145_2215_stow_z3)
Lux_20241115_2145_2215_stow_z3 = Lux_20241115_2145_2215_stow_z3[Lux_20241115_2145_2215_stow_z3>0]

autocorr_inflow_20241115_2145_2215_stow = np.correlate(loads_inflow_20Hz_20241115_2145_2215_stow.W_ax_Low.dropna(), loads_inflow_20Hz_20241115_2145_2215_stow.W_ax_Low.dropna(), mode='full') 
