utau_mast3_z1_20241118_1840_1900_stow = (mast3_uw_z1_20241118_1840_1900_stow**2+mast3_vw_z1_20241118_1840_1900_stow**2)**(1/4) 
utau_mast3_z2_20241118_1840_1900_stow = (mast3_uw_z2_20241118_1840_1900_stow**2+mast3_vw_z2_20241118_1840_1900_stow**2)**(1/4) 
