heights = [2.75,5.5,11] 
fs = 20

# Spectra
import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import welch
from numpy import hanning
import math

overlap = 0
nblock = len(loads_inflow_20Hz_20241118_1635_1655_operation.U_ax_Low)
win = np.hamming(math.floor(nblock/10))

fu_loads_inflow_20Hz_20241118_1635_1655_operation_z1, Pxxfu_loads_inflow_20Hz_20241118_1635_1655_operation_z1 = welch(loads_inflow_20Hz_20241118_1635_1655_operation.U_ax_Low.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfu_loads_inflow_20Hz_20241118_1635_1655_operation_z1 = fu_loads_inflow_20Hz_20241118_1635_1655_operation_z1*heights[0]/H1_U_ax_20241118_1635_1655_operation_z1
nPxxfu_loads_inflow_20Hz_20241118_1635_1655_operation_z1 = (fu_loads_inflow_20Hz_20241118_1635_1655_operation_z1*Pxxfu_loads_inflow_20Hz_20241118_1635_1655_operation_z1)/loads_inflow_20Hz_20241118_1635_1655_operation.U_ax_Low.std()**2

fu_loads_inflow_20Hz_20241118_1635_1655_operation_z2, Pxxfu_loads_inflow_20Hz_20241118_1635_1655_operation_z2 = welch(loads_inflow_20Hz_20241118_1635_1655_operation.U_ax_Mid.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
