autocorr_inflow_20241118_1635_1655_operation = np.correlate(loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna(), loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna(), mode='full') 
autocorr_inflow_20241118_1635_1655_operation /= np.sqrt(np.dot(loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna(), loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna()) * np.dot(loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna(), loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna()))  # Normalize the result
lags = np.arange(-len(loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna()) + 1, len(loads_inflow_20Hz_20241118_1635_1655_operation.W_ax_Top.dropna()))
Y = (lags, autocorr_inflow_20241118_1635_1655_operation)
Lwx_20241118_1635_1655_operation_z3 = Y[0][np.where(Y[1]==find_nearest(Y[1], value=1/np.e))]*(1/fs)*abs(H1_wspd_20241118_1635_1655_operation_z3)
Lwx_20241118_1635_1655_operation_z3 = Lwx_20241118_1635_1655_operation_z3[Lwx_20241118_1635_1655_operation_z3>0]

Lux_profile_inflow_20241118_1635_1655_operation = pd.Series([Lux_20241118_1635_1655_operation_z1,Lux_20241118_1635_1655_operation_z2,Lux_20241118_1635_1655_operation_z3])
Lwx_profile_inflow_20241118_1635_1655_operation = pd.Series([Lwx_20241118_1635_1655_operation_z1,Lwx_20241118_1635_1655_operation_z2,Lwx_20241118_1635_1655_operation_z3])
 


#%% Mast 1

U_corr_mast1_20241118_1635_1655_operation_z1 = pd.Series(loads_mast_20Hz_20241118_1635_1655_operation.m1_U_ax_Low)
