V_corr_mast1_20241118_1635_1655_operation_z3[V_corr_mast1_20241118_1635_1655_operation_z3.isna()==False] = scipy.signal.detrend(V_corr_mast1_20241118_1635_1655_operation_z3.dropna()) 

W_corr_mast1_20241118_1635_1655_operation_z1[W_corr_mast1_20241118_1635_1655_operation_z1.isna()==False] = scipy.signal.detrend(W_corr_mast1_20241118_1635_1655_operation_z1.dropna()) 
W_corr_mast1_20241118_1635_1655_operation_z2[W_corr_mast1_20241118_1635_1655_operation_z2.isna()==False] = scipy.signal.detrend(W_corr_mast1_20241118_1635_1655_operation_z2.dropna()) 
W_corr_mast1_20241118_1635_1655_operation_z3[W_corr_mast1_20241118_1635_1655_operation_z3.isna()==False] = scipy.signal.detrend(W_corr_mast1_20241118_1635_1655_operation_z3.dropna()) 

