# Reynolds stresses and length scales (south2)

mast1_uv_z1_20241118_1635_1655_operation = (U_corr_mast1_20241118_1635_1655_operation_z1*V_corr_mast1_20241118_1635_1655_operation_z1).mean()-(U_corr_mast1_20241118_1635_1655_operation_z1.mean()*V_corr_mast1_20241118_1635_1655_operation_z1.mean());
mast1_vw_z1_20241118_1635_1655_operation = (V_corr_mast1_20241118_1635_1655_operation_z1*W_corr_mast1_20241118_1635_1655_operation_z1).mean()-(V_corr_mast1_20241118_1635_1655_operation_z1.mean()*W_corr_mast1_20241118_1635_1655_operation_z1.mean());
mast1_uw_z1_20241118_1635_1655_operation = (U_corr_mast1_20241118_1635_1655_operation_z1*W_corr_mast1_20241118_1635_1655_operation_z1).mean()-(U_corr_mast1_20241118_1635_1655_operation_z1.mean()*W_corr_mast1_20241118_1635_1655_operation_z1.mean());
