mast1_vw_z2_20241118_1635_1655_operation = (V_corr_mast1_20241118_1635_1655_operation_z2*W_corr_mast1_20241118_1635_1655_operation_z2).mean()-(V_corr_mast1_20241118_1635_1655_operation_z2.mean()*W_corr_mast1_20241118_1635_1655_operation_z2.mean());
mast1_uw_z2_20241118_1635_1655_operation = (U_corr_mast1_20241118_1635_1655_operation_z2*W_corr_mast1_20241118_1635_1655_operation_z2).mean()-(U_corr_mast1_20241118_1635_1655_operation_z2.mean()*W_corr_mast1_20241118_1635_1655_operation_z2.mean());
mast1_wT_z2_20241118_1635_1655_operation = (W_corr_mast1_20241118_1635_1655_operation_z2*Ts_corr_mast1_20241118_1635_1655_operation_z2).mean()-(W_corr_mast1_20241118_1635_1655_operation_z2.mean()*Ts_corr_mast1_20241118_1635_1655_operation_z2.mean());

mast1_uv_z3_20241118_1635_1655_operation = (U_corr_mast1_20241118_1635_1655_operation_z3*V_corr_mast1_20241118_1635_1655_operation_z3).mean()-(U_corr_mast1_20241118_1635_1655_operation_z3.mean()*V_corr_mast1_20241118_1635_1655_operation_z3.mean());
mast1_vw_z3_20241118_1635_1655_operation = (V_corr_mast1_20241118_1635_1655_operation_z3*W_corr_mast1_20241118_1635_1655_operation_z3).mean()-(V_corr_mast1_20241118_1635_1655_operation_z3.mean()*W_corr_mast1_20241118_1635_1655_operation_z3.mean());
mast1_uw_z3_20241118_1635_1655_operation = (U_corr_mast1_20241118_1635_1655_operation_z3*W_corr_mast1_20241118_1635_1655_operation_z3).mean()-(U_corr_mast1_20241118_1635_1655_operation_z3.mean()*W_corr_mast1_20241118_1635_1655_operation_z3.mean());
mast1_wT_z3_20241118_1635_1655_operation = (W_corr_mast1_20241118_1635_1655_operation_z3*Ts_corr_mast1_20241118_1635_1655_operation_z3).mean()-(W_corr_mast1_20241118_1635_1655_operation_z3.mean()*Ts_corr_mast1_20241118_1635_1655_operation_z3.mean());

utau_mast1_z1_20241118_1635_1655_operation = (mast1_uw_z1_20241118_1635_1655_operation**2+mast1_vw_z1_20241118_1635_1655_operation**2)**(1/4) 
utau_mast1_z2_20241118_1635_1655_operation = (mast1_uw_z2_20241118_1635_1655_operation**2+mast1_vw_z2_20241118_1635_1655_operation**2)**(1/4) 
