L_mast1_z1_20241118_1635_1655_operation = -1*(utau_mast1_z1_20241118_1635_1655_operation**3)/(0.4*(9.81/H2_Ts_20241118_1635_1655_operation_z1)*mast1_wT_z1_20241118_1635_1655_operation)
L_mast1_z2_20241118_1635_1655_operation = -1*(utau_mast1_z2_20241118_1635_1655_operation**3)/(0.4*(9.81/H2_Ts_20241118_1635_1655_operation_z2)*mast1_wT_z2_20241118_1635_1655_operation)
L_mast1_z3_20241118_1635_1655_operation = -1*(utau_mast1_z3_20241118_1635_1655_operation**3)/(0.4*(9.81/H2_Ts_20241118_1635_1655_operation_z3)*mast1_wT_z3_20241118_1635_1655_operation)

