nPxxfw_loads_mast1_20Hz_20241118_1635_1655_operation_z1 = (fw_loads_mast1_20Hz_20241118_1635_1655_operation_z1*Pxxfw_loads_mast1_20Hz_20241118_1635_1655_operation_z1)/loads_mast_20Hz_20241118_1635_1655_operation.m1_W_ax_Low.std()**2

fw_loads_mast1_20Hz_20241118_1635_1655_operation_z2, Pxxfw_loads_mast1_20Hz_20241118_1635_1655_operation_z2 = welch(loads_mast_20Hz_20241118_1635_1655_operation.m1_W_ax_Mid.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
