#%% Smooth high frequency region

index_highfreq_loads_mast_20Hz_20241118_1635_1655_operation_z1 = list(np.where([abs(nfu_loads_mast1_20Hz_20241118_1635_1655_operation_z1)>0.3]))
nPxxfu_smooth_loads_mast_20Hz_20241118_1635_1655_operation_z1 = nPxxfu_loads_mast1_20Hz_20241118_1635_1655_operation_z1[index_highfreq_loads_mast_20Hz_20241118_1635_1655_operation_z1[0][0]:len(nPxxfu_loads_mast1_20Hz_20241118_1635_1655_operation_z1)]
