#%% LS exponential fit method

autocorr_mast1_20241120_2000_2030_stow2 = np.correlate(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna(), loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna(), mode='full') 
autocorr_mast1_20241120_2000_2030_stow2 /= np.sqrt(np.dot(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna(), loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna()) * np.dot(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna(), loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna()))  # Normalize the result
lags = np.arange(-len(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna()) + 1, len(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Low.dropna()))
Y = (lags, autocorr_mast1_20241120_2000_2030_stow2)
Lux_20241120_2000_2030_stow2_z1 = Y[0][np.where(Y[1]==find_nearest(Y[1], value=1/np.e))]*(1/fs)*abs(H2_wspd_20241120_2000_2030_stow2_z1)
Lux_mast1_20241120_2000_2030_stow2_z1 = Lux_20241120_2000_2030_stow2_z1[Lux_20241120_2000_2030_stow2_z1>0]

autocorr_mast1_20241120_2000_2030_stow2 = np.correlate(loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Mid.dropna(), loads_mast_20Hz_20241120_2000_2030_stow2.m1_U_ax_Mid.dropna(), mode='full') 
