#%% PSD analysis

heights = [2.75,5.5,11] 
fs = 20

# Spectra
import numpy as np
import matplotlib.pyplot as plt
from scipy.signal import welch
from numpy import hanning
import math

overlap = 0
nblock = len(loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Low)
win = np.hamming(math.floor(nblock/10))

fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1, Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = welch(loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Low.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1*heights[0]/H1_U_ax_20241120_2200_2230_stow3_z1
nPxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = (fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1*Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z1)/loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Low.std()**2

fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2, Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2 = welch(loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Mid.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2 = fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2*heights[1]/H1_U_ax_20241120_2200_2230_stow3_z2
nPxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2 = (fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2*Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z2)/loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Mid.std()**2
 
fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3, Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3 = welch(loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Top.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3 = fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3*heights[2]/H1_U_ax_20241120_2200_2230_stow3_z3
nPxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3 = (fu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3*Pxxfu_loads_inflow_20Hz_20241120_2200_2230_stow3_z3)/loads_inflow_20Hz_20241120_2200_2230_stow3.U_ax_Top.std()**2              
    
fw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1, Pxxfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = welch(loads_inflow_20Hz_20241120_2200_2230_stow3.W_ax_Low.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = fw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1*heights[0]/H1_W_ax_20241120_2200_2230_stow3_z1
nPxxfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1 = (fw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1*Pxxfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z1)/loads_inflow_20Hz_20241120_2200_2230_stow3.W_ax_Low.std()**2

fw_loads_inflow_20Hz_20241120_2200_2230_stow3_z2, Pxxfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z2 = welch(loads_inflow_20Hz_20241120_2200_2230_stow3.W_ax_Mid.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfw_loads_inflow_20Hz_20241120_2200_2230_stow3_z2 = fw_loads_inflow_20Hz_20241120_2200_2230_stow3_z2*heights[1]/H1_W_ax_20241120_2200_2230_stow3_z2
