mast3_wT_z3_20241120_1630_1700_operation = (W_corr_mast3_20241120_1630_1700_operation_z3*Ts_corr_mast3_20241120_1630_1700_operation_z3).mean()-(W_corr_mast3_20241120_1630_1700_operation_z3.mean()*Ts_corr_mast3_20241120_1630_1700_operation_z3.mean());

utau_mast3_z1_20241120_1630_1700_operation = (mast3_uw_z1_20241120_1630_1700_operation**2+mast3_vw_z1_20241120_1630_1700_operation**2)**(1/4) 
utau_mast3_z2_20241120_1630_1700_operation = (mast3_uw_z2_20241120_1630_1700_operation**2+mast3_vw_z2_20241120_1630_1700_operation**2)**(1/4) 
