#%%

overlap = 0
nblock = len(loads_mast_20Hz_20241120_1630_1700_operation.m3_U_ax_Low)
win = np.hamming(math.floor(nblock/10))

fu_loads_mast3_20Hz_20241120_1630_1700_operation_z1, Pxxfu_loads_mast3_20Hz_20241120_1630_1700_operation_z1 = welch(loads_mast_20Hz_20241120_1630_1700_operation.m3_U_ax_Low.dropna(), fs, window=win, noverlap=overlap, nfft=nblock, detrend='constant', return_onesided=True)
nfu_loads_mast3_20Hz_20241120_1630_1700_operation_z1 = fu_loads_mast3_20Hz_20241120_1630_1700_operation_z1*heights[0]/H3_U_ax_20241120_1630_1700_operation_z1
nPxxfu_loads_mast3_20Hz_20241120_1630_1700_operation_z1 = (fu_loads_mast3_20Hz_20241120_1630_1700_operation_z1*Pxxfu_loads_mast3_20Hz_20241120_1630_1700_operation_z1)/loads_mast_20Hz_20241120_1630_1700_operation.m3_U_ax_Low.std()**2

